 {id:'oldtown',title:'旧城手记',kind:'散文',language:'英语',format:'EPUB',cover:'slate',quality:2,status:'paused',done:4,total:18,phase:2,fraction:.35,lastRead:1,style:'忠实清晰',termsMode:'auto'},
 {id:'garden',title:'雨后的花园',kind:'诗集',language:'法语',format:'EPUB',cover:'garden',quality:3,status:'complete',done:12,total:12,phase:0,fraction:0,lastRead:2,style:'文学雅译',termsMode:'auto'},
 {id:'letters',title:'北岸来信',kind:'小说',language:'英语',format:'DOCX',cover:'rose',quality:3,status:'ready',done:0,total:16,phase:0,fraction:0,lastRead:0,style:'现代叙事',termsMode:'auto',terms:[{source:'Eleanor Vale',target:'埃莉诺·维尔',category:'人物'},{source:'Greyhaven',target:'灰港',category:'地点'},{source:'The Glass House',target:'玻璃屋',category:'物件 / 地点'}]},
 {id:'field',title:'田野调查笔记',kind:'技术文档',language:'英语',format:'PDF',cover:'plain',quality:1,status:'ready',done:0,total:6,phase:0,fraction:0,lastRead:0,style:'专业文档',termsMode:'auto'}
