function nameEntries(b){if(!b.names)b.names=b.id.startsWith('import-')||b.status==='ready'?[]:nameSamples();return b.names;}
function openNames(b){if(route.sheet==='book-menu'){stack.pop();route=stack.at(-1);}move('names',b.id);}
function renderNames(){const b=activeBook(),list=nameEntries(b);$('#namesScreen').innerHTML=`<div class="names-heading"><p class="overline">${esc(b.title)}</p><h1>译名</h1><p>自动保持一致，需要时再修改。</p></div>${list.length?`<div class="name-list">${list.map((t,i)=>`<div class="name-row"><div class="name-pair"><span class="name-source">${esc(t.source)}</span><span class="name-target">${esc(t.target)}</span></div><button data-action="edit-name" data-book="${esc(b.id)}" data-name="${i}" aria-label="修改 ${esc(t.source)} 的译名">修改</button></div>`).join('')}</div>`:'<div class="names-empty"><h2>译名会随翻译积累</h2><p>不用提前整理，可以直接开始翻译。</p></div>'}<p class="names-footnote">修改只用于后续处理，不会自动重译已完成章节。</p>`;}
